<div class="row g-3 mb-4">
<?php foreach ([['Domains', $zones, 'Managed authoritative zones'], ['Active members', count(array_filter($servers, fn($s) => $s['state'] === 'active')), 'Independent DNS servers'], ['Pending deployments', $pending, 'Server / zone revisions behind'], ['Failed jobs', $failed, 'Require operator attention']] as [$label, $value, $hint]): ?>
<div class="col-6 col-xl-3"><section class="card metric"><div class="card-body"><div class="text-secondary small"><?= $escape($label) ?></div><div class="metric-value"><?= $escape($value) ?></div><div class="small text-secondary"><?= $escape($hint) ?></div></div></section></div><?php endforeach; ?></div>
<div class="row g-4"><section class="col-xl-8"><div class="card"><div class="card-header d-flex justify-content-between"><h2>Member health</h2><a href="/servers">Manage members →</a></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Member</th><th>Location</th><th>State</th><th>Last health</th></tr></thead><tbody>
<?php foreach ($servers as $server): $stale = !$server['health_at'] || strtotime($server['health_at'] . ' UTC') < time() - 300; ?><tr><td><strong><?= $escape($server['name']) ?></strong><div class="small text-secondary"><?= $escape($server['address']) ?></div></td><td><?= $escape($server['location']) ?></td><td><span class="badge <?= $stale || $server['last_error'] ? 'text-bg-warning' : 'text-bg-success' ?>"><?= $escape($server['last_error'] ? 'attention' : ($stale ? 'unverified' : $server['state'])) ?></span></td><td class="small"><?= $escape($server['health_at'] ?? 'Not checked') ?></td></tr><?php endforeach; ?>
<?php if (!$servers): ?><tr><td colspan="4" class="empty-state">Your network starts here. <a href="/servers">Onboard your first member.</a></td></tr><?php endif; ?></tbody></table></div></div></section>
<section class="col-xl-4"><div class="card info-card"><div class="card-body"><div class="eyebrow">DESIGNED FOR INDEPENDENCE</div><h2>Your DNS keeps serving.</h2><p>Members serve local signed zones. Panel or database outages do not stop BIND.</p><hr><p class="small mb-0">Publish creates a revision. Each member acknowledges it after BIND serves the expected SOA. Unreachable members remain pending.</p></div></div></section></div>
<section class="card mt-4"><div class="card-header"><h2>Recent activity</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Time</th><th>Action</th><th>Subject</th><th>Actor</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td class="small"><?= $escape($event['created_at']) ?></td><td><?= $escape($event['action']) ?></td><td><?= $escape($event['subject']) ?></td><td><?= $escape($event['actor']) ?></td></tr><?php endforeach; ?><?php if (!$events): ?><tr><td colspan="4" class="empty-state">No activity yet.</td></tr><?php endif; ?></tbody></table></div></section>
